using System;using System.Drawing;using System.Drawing.Imaging;using System.IO;using System.Text;using CuteMouseEffects;
class CursorAssetGenerator{sealed class T{public string Id;public Color S,A,B,G,C;public T(string i,Color s,Color a,Color b,Color g,Color c){Id=i;S=s;A=a;B=b;G=g;C=c;}}static readonly T[] Themes={new T("warm",Color.FromArgb(54,37,34),Color.FromArgb(235,102,94),Color.FromArgb(244,193,69),Color.FromArgb(255,225,183),Color.FromArgb(92,48,42)),new T("mono",Color.FromArgb(8,8,10),Color.FromArgb(250,250,252),Color.FromArgb(122,126,134),Color.White,Color.FromArgb(30,31,34)),new T("cool",Color.FromArgb(22,29,55),Color.FromArgb(92,151,255),Color.FromArgb(154,119,255),Color.FromArgb(218,242,255),Color.FromArgb(39,61,118)),new T("galaxy",Color.FromArgb(17,11,43),Color.FromArgb(177,82,255),Color.FromArgb(34,211,238),Color.FromArgb(248,247,255),Color.FromArgb(219,86,239)),new T("sakura",Color.FromArgb(58,29,49),Color.FromArgb(255,91,139),Color.FromArgb(255,184,107),Color.FromArgb(255,240,246),Color.FromArgb(143,46,89)),new T("forest",Color.FromArgb(14,45,40),Color.FromArgb(31,190,138),Color.FromArgb(183,217,76),Color.FromArgb(232,255,246),Color.FromArgb(23,107,90))};static void Main(string[] a){string root=a.Length>0?a[0]:"cursor-shapes",v=Path.Combine(root,"vectors");Directory.CreateDirectory(v);foreach(var s in CursorShapes.All){File.WriteAllText(Path.Combine(v,s.Id+".svg"),Svg(s.Id),new UTF8Encoding(false));foreach(var t in Themes)Render(root,s.Id,t);}File.WriteAllText(Path.Combine(v,"hand.svg"),Svg("hand"),new UTF8Encoding(false));foreach(var t in Themes)Render(root,"hand",t);Preview(root);}static void Render(string root,string id,T t){using(var b=new Bitmap(48,48,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(b)){g.Clear(Color.Transparent);CursorShapes.Draw(g,id,new RectangleF(2,2,44,44),t.S,t.A,t.B,t.G,t.C);}string p=Path.Combine(root,id+"-"+t.Id+".png");b.Save(p,ImageFormat.Png);Cur(p,Path.Combine(root,id+"-"+t.Id+".cur"),id);}}static void Cur(string png,string cur,string id){byte[] d=File.ReadAllBytes(png);using(var f=new FileStream(cur,FileMode.Create))using(var w=new BinaryWriter(f)){w.Write((ushort)0);w.Write((ushort)2);w.Write((ushort)1);w.Write((byte)48);w.Write((byte)48);w.Write((byte)0);w.Write((byte)0);w.Write((ushort)(id=="hand"?19:6));w.Write((ushort)(id=="hand"?3:5));w.Write((uint)d.Length);w.Write((uint)22);w.Write(d);}}static void Preview(string root){using(var b=new Bitmap(720,150))using(var g=Graphics.FromImage(b)){g.Clear(Color.FromArgb(232,228,220));using(var d=new SolidBrush(Color.FromArgb(35,39,43)))using(var f=new Font("Microsoft YaHei UI",10)){for(int i=0;i<6;i++){var s=CursorShapes.All[i];int x=18+i*118;g.FillRectangle(d,x,12,96,96);using(var im=Image.FromFile(Path.Combine(root,s.Id+"-warm.png")))g.DrawImage(im,x+24,34,48,48);using(var z=new SolidBrush(Color.FromArgb(45,45,45)))g.DrawString(s.Name,f,z,x+27,116);}}b.Save(Path.Combine(root,"shape-preview.png"),ImageFormat.Png);}}
 static string Svg(string id){string body,detail;if(id=="hand"){body="M20 3 C17 3 16 6 16 11 C16 15 16 19 16 23 L12 19 C9 16 6 18 7 22 L15 36 C18 43 25 46 32 42 C39 38 41 30 38 23 C37 19 33 19 32 23 C32 17 28 16 26 20 L26 10 C26 5 23 3 20 3 Z";detail="M17 25 C22 23 27 24 31 29 M18 35 C23 39 29 39 34 35";}else if(id=="star"){body="M5 4 C13 4 25 10 31 17 C37 13 44 16 43 24 C43 28 40 31 37 32 C45 34 46 40 41 44 C35 48 28 43 24 36 C21 43 17 46 12 42 C8 39 9 34 11 30 C7 29 4 25 6 20 C8 16 11 16 13 16 C9 12 3 8 5 4 Z";detail="M9 8 C10 20 15 31 21 35 M31 18 C37 20 39 25 36 30 M13 10 C16 8 20 10 19 14 C17 17 13 15 13 10 Z";}else if(id=="moon"){body="M5 4 C18 8 34 16 43 24 C47 29 41 34 34 32 C41 38 39 45 32 43 C28 41 25 36 22 33 C20 41 15 45 11 41 C8 38 9 33 10 29 C7 21 5 13 5 4 Z";detail="M8 8 C13 13 17 18 20 25 M16 28 C22 25 28 27 34 31 M13 35 C18 33 23 37 28 41 M13 14 C20 13 25 17 28 23";}else if(id=="feather"){body="M5 4 C20 5 37 12 42 24 C46 35 38 42 27 41 C32 44 38 46 35 48 C31 50 27 44 23 41 C13 42 7 35 6 25 C4 16 3 7 5 4 Z";detail="M7 7 C16 19 25 31 35 44 M14 17 C20 16 24 18 27 22 M20 26 C27 24 32 27 36 31 M15 30 C20 32 24 35 27 38";}else if(id=="drop"){body="M5 4 L20 14 L32 9 L31 22 L43 29 L34 35 L34 44 L25 40 L19 47 L15 38 L5 40 L9 29 L2 22 L13 18 Z";detail="M8 8 L22 17 L30 13 M12 29 L20 36 L27 42";}else if(id=="petal"){body="M6 4 L38 19 L29 25 L42 34 L25 46 L27 35 L9 30 L18 22 Z";detail="M11 9 L29 19 L22 25 L35 33 L28 39";}else{body="M6 3 C13 2 23 7 22 15 C32 11 40 15 39 24 C47 25 48 34 40 38 C42 45 33 48 27 42 C20 48 10 44 11 35 C3 33 4 24 11 21 C5 17 2 8 6 3 Z";detail="M9 18 C17 23 29 22 37 18 M10 32 C20 37 32 36 40 31 M14 41 C20 44 26 44 30 41";}return "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 48 48'><path d='"+body+"' fill='#ffe1b7' stroke='#362522' stroke-width='5.4' stroke-linejoin='round'/><path d='"+detail+"' fill='none' stroke='#eb665e' stroke-width='2.4' stroke-linecap='round' stroke-linejoin='round'/></svg>";}
